        listeners.forEach(l -> l.onInsert(word));
    }

    private void notifyDelete(String word) {
        listeners.forEach(l -> l.onDelete(word));
    }

    private void notifySearch(String word, boolean found) {
        listeners.forEach(l -> l.onSearch(word, found));
